window.kbPageData["views/entry/k-069b062c908f8ae9"] = {"key":"entry/k-069b062c908f8ae9","state":{"route":"entry/k-069b062c908f8ae9"},"node":{"id":"k-069b062c908f8ae9","mode":"k","title":"加强重点领域风险防范化解和安全能力建设","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["law","party"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","政治理论","经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"新的形势和任务，对政府工作提出了更高要求。\n各级政府及其工作人员要深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚\n定“四个自信”、做到“两个维护”①，自觉在思想上政治上行动上同以习近平同志为核心\n的党中央保持高度一致。坚决扛起全面从严治党政治责任，巩固拓展深入贯彻中央八项规定\n精神学习教育②…","sources":[{"id":"a5cdcb95febb1cc2","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"新的形势和任务，对政府工作提出了更高要求。\n各级政府及其工作人员要深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚\n定“四个自信”、做到“两个维护”①，自觉在思想上政治上行动上同以习近平同志为核心\n的党中央保持高度一致。坚决扛起全面从严治党政治责任，巩固拓展深入贯彻中央八项规定\n精神学习教育②成果，加强对权力配置、运行的规范和监督，纵深推进政府党风廉政建设和\n反腐败斗争，深化整治群众身边不正之风和腐败问题。牢固树立和践行正确政绩观③，坚持\n为人民出政绩、以实干出政绩，自觉按规律办事。","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"feea5fd5926b1697","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"李强强调，蓝图已经绘就，奋进正当其时。我们要更加紧密地团结在以习近平同志为核\n心的党中央周围，高举中国特色社会主义伟大旗帜，以习近平新时代中国特色社会主义思\n想为指导，万众一心、砥砺前行，奋力实现全年经济社会发展目标任务，确保“十五五”良\n好开局，为以中国式现代化全面推进强国建设、民族复兴伟业不懈奋斗！","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"a7c6dbe87574bda8","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治方针，\n落实“爱国者治港”、“爱国者治澳”原则①，提升港澳依法治理效能，促进港澳经济社会\n发展。支持港澳更好融入和服务国家发展大局，发挥港澳背靠祖国、联通世界独特优势和重\n要作用，促进香港、澳门长期繁荣稳定。\n我们要深入贯彻新时代党解决台湾问题的总体方略②，坚持一个中国原则和“九二共识”，\n坚决打击“台独”分裂势力，反对外部势力干涉，推动两岸关系和平发展、推进祖国统一大\n业。深化两岸交流合作和融合发展，共同传承弘扬中华文化，落实台湾同胞享受同等待遇政\n策，增进两岸同胞福祉，共同开创民族复兴伟业。","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":55,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"bf7189eda8acd937","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要以铸牢中华民族共同体意识为主线①，积极促进各民族广泛交往交流交融，加快\n民族地区现代化建设步伐，推进中华民族共同体建设。坚持党的宗教工作基本方针，坚持我\n国宗教中国化②方向，加强宗教事务治理法治化。全面贯彻党的侨务政策，维护海外侨胞和\n归侨侨眷合法权益，更好凝聚侨心侨力。","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":52,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"17f556fab3c26093","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"过去一年，国防和军队现代化建设取得新的成就。新的一年，我们要深入贯彻习近平强\n军思想①，贯彻新时代军事战略方针，坚持党对人民军队的绝对领导②，全面深入贯彻军委\n主席负责制，以政治建军为引领，持续深化政治整训，接续打好实现建军一百年奋斗目标③\n攻坚战。扎实推进练兵备战，加快先进战斗力建设，提高捍卫国家主权、安全、发展利益的\n战略能力。抓好军队建设“十五五”规划编制，实施国防发展重大工程，实施军事理论现代\n化推进工程。协力推进跨军地改革，优化国防科技工业体系和布局，巩固提高一体化国家战\n略体系和能力。加快国防动员能力建设，深化全民国防教育。各级政府要大力支持国防和军\n队建设，深入开展“双拥”工作，巩固军政军民团结。","source":{"doc":"6cbfb01fe723bba64b75","first":53,"last":54,"page":53,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"47d68837fae0378c","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要强化法治政府建设①，深入推进依法行政，严格依照宪法法律履职尽责。\n自觉接受同级人大及其常委会的监督，自觉接受人民政协的民主监督，自觉接受社会\n和舆论监督。提高审计监督质效②。坚持科学、民主、依法决策。扎实做好政务公开工作，\n加强政策宣传解读。支持工会、共青团、妇联等群团组织更好发挥作用。深化事业单位改革。\n健全规范涉企行政执法长效机制。以“高效办成一件事”为牵引，持续优化政务服务，加快\n数字政府建设。着力提升行政效能，沉下心来抓落实，认认真真解决问题，提高对党中央决\n策部署一贯到底的执行力穿透力。各级政府要树牢大局观，准确把握在全国发展大局中的定\n位，善于把国家战略、市场需求和地区优势结合起来，因地制宜探索高质量发展新模式。完\n善差异化考核评价体系，持续深化整治形式主义为基层减负③，让广大干部心无旁骛抓落实、\n办实事。营造良好政治环境、人才环境、营商环境、舆论环境，在全社会凝聚推动高质量\n发展的强大合力。","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"1c5a2f939216b230","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"我们要坚持独立自主的和平外交政策①，坚持走和平发展道路，拓展全球伙伴关系网络，\n坚决反对霸权主义和强权政治，维护国际公平正义。中国愿同国际社会一道，倡导平等有序\n的世界多极化、普惠包容的经济全球化，推动落实全球发展倡议、全球安全倡议、全球文\n明倡议、全球治理倡议②，积极参与全球治理体系改革和建设，推动国际秩序朝着更加公正\n合理的方向发展，携手构建人类命运共同体，共创世界和平发展美好未来。","source":{"doc":"6cbfb01fe723bba64b75","first":55,"last":56,"page":55,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"d81d4ef637c273d2","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"维护国家安全和社会稳定。全面贯彻总体国家安全观①，健全国家安全体系，加强重点\n领域国家安全能力建设。强化公共安全治理，提升重要基础设施本质安全水平，持续夯实安\n全生产、防灾减灾基层基础，全面完成安全生产治本攻坚三年行动②。加强气象、水文、\n地质灾害、森林草原火灾、地震监测预报预警。加快补齐北方地区防洪排涝抗灾基础设施、\n应急处置等短板。加快建设现代化水网。健全巨灾保险保障体系。严格食品、药品、重点工\n业产品、特种设备等安全监管。完善社会治理体系，引导支持社会组织、人道救助、志愿服\n务、公益慈善等健康发展，推动行业协会商会改革发展。坚持和发展新时代“枫桥经验”③，\n推进综治中心规范化建设，完善社区治理，推进矛盾纠纷预防和多元化解。加强社会心理疏\n导。深入推进信访工作法治化，集中化解信访问题。深化社会治安整体防控体系和能力建设，\n健全扫黑除恶常态化机制，加大预防和打击电信网络诈骗、毒品犯罪等力度，建设更高水\n平的平安中国。","source":{"doc":"6cbfb01fe723bba64b75","first":49,"last":49,"page":49,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"3197796e3b42dba0","label":"加强重点领域风险防范化解和安全能力建设","topic":"年度政府工作","category":"时政","text":"（十）加强重点领域风险防范化解和安全能力建设。统筹防风险和促发展，进一步增\n强发展韧性，坚决守牢安全底线，促进社会和谐稳定。\n着力稳定房地产市场①。因城施策控增量、去库存、优供给，探索多渠道盘活存量商品\n房，鼓励收购存量商品房重点用于保障性住房等。深化住房公积金制度改革。优化保障性住\n房供给，加快危旧房改造。有序推动安全舒适绿色智慧的“好房子”建设，实施房屋品质\n提升工程和物业服务质量提升行动。进一步发挥“保交房”的白名单制度作用，防范债务违\n约风险。深入推进房地产发展新模式的基础制度和配套政策建设。\n积极有序化解地方政府债务风险②。支持各地用足用好政策，加快化解隐性债务风险，\n严防虚假化债，坚决把遏制违规新增隐性债务作为铁的纪律。加大金融、财政支持力度，优\n化债务重组和置换办法，多措并举化解地方政府融资平台经营性债务风险，分类有序推动改\n革转型。优化债务监测考核指标，构建统一的政府债务管理长效机制。\n积极稳妥化解金融领域风险③。充实地方中小金融机构风险处置资源和手段。坚持市场\n化法治化原则，有序推进高风险机构处置。多渠道加大资本补充力度，稳妥处置金融机构不\n良资产。加强金融监管协同，防范打击非法金融活动。强化金融风险监测预警和早期纠正，\n提高风险源头防控能力。","source":{"doc":"6cbfb01fe723bba64b75","first":48,"last":48,"page":48,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"law","title":"法治政府与依法行政"},{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-069b062c908f8ae9":[]}};
